// === Tab: Piece ===
class Piece {
	constructor(pos, ang, type, flip, id, fll) {
		this.pos = createVector(random([-2 * width, 2 * width]), random([-2 * height, 2 * height]));
		this.tpos = pos;
		this.ang = 0;
		this.tang = ang;
		this.type = type;
		this.flip = flip;
		this.tflip = flip;
		this.id = id;
		this.fll = fll;
	}
	show() {
		push();
		translate(this.pos);
		rotate(this.ang);
		scale(this.flip, 1);
		fill(this.fll);
		if (this.type == 3) shearY(QUARTER_PI);
		beginShape();
		switch (this.type) {
			case 0: // small triangle A
				vertex(dim, -dim);
				vertex(dim, dim);
				vertex(-dim, dim);
				break;
			case 1: //small triangle B
				vertex(-dim, -dim);
				vertex(dim, dim);
				vertex(-dim, dim);
				break;
			case 2: // square
				vertex(-dim, -dim);
				vertex(dim, -dim);
				vertex(dim, dim);
				vertex(-dim, dim);
				break;
			case 3: // paralellogram
				vertex(-dim, 0);
				vertex(dim, 0);
				vertex(dim, 2 * dim);
				vertex(-dim, 2 * dim);
				break;
			case 4: // medium triangle
				vertex(dim, -dim);
				vertex(3 * dim, dim);
				vertex(-dim, dim);
				break;
			case 5: // large triangle A
				vertex(-2 * dim, -2 * dim);
				vertex(-2 * dim, 2 * dim);
				vertex(2 * dim, 2 * dim);
				break;
			case 6: // large triangle B
				vertex(-2 * dim, -2 * dim);
				vertex(2 * dim, -2 * dim);
				vertex(-2 * dim, 2 * dim);
				break;
		}
		endShape(CLOSE);
		pop();
	}

	move() {
		this.pos.lerp(this.tpos, 0.1);
		this.ang = lerp(this.ang, this.tang, 0.1);
		this.flip = lerp(this.flip, this.tflip, 0.2);
	}

}

